package com.bananalab.lite;
import android.content.*;import android.graphics.*;import java.io.*;import java.util.*;import java.util.regex.*;import org.json.*;
/** Real last-layer fine tuning of Banana's own weights. Not a full-network trainer. */
final class NeuralTraining{
 static BananaTransformer chat(Context c)throws Exception{return new BananaTransformer(ModelDepot.open(c,"chat"),c.getAssets().open("chat34/vocab.txt"),c.getAssets().open("chat34/tokenizer.json"));}
 static List<HeadTrainer.Token> tokens(BananaTransformer model,JSONArray rows)throws Exception{List<HeadTrainer.Token> result=new ArrayList<>();for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);List<Integer> prompt=model.encode(row.getString("question"),4096),answer=model.encode(row.getString("answer"),4096);if(prompt.size()>48||answer.size()>24)throw new IllegalArgumentException("El ejemplo supera48 tokens de pregunta o24 de respuesta; no lo entrené parcialmente.");BananaTransformer.Session session=model.session();session.step(2);session.step(3);for(int n:prompt)session.step(n);session.step(4);answer.add(5);for(int n:answer){result.add(new HeadTrainer.Token(session.features,n));session.step(n);}}return result;}
 static JSONArray defaultRows(String split)throws Exception{JSONArray out=new JSONArray();String[][] rows=split.equals("train")?new String[][]{{"como se llama este proyecto","se llama banana ."},{"podes responder cualquier cosa","soy un modelo pequeno y experimental ."}}:split.equals("eval")?new String[][]{{"cual es el nombre del proyecto","se llama banana ."},{"entendes absolutamente todo","soy un modelo pequeno y experimental ."}}:new String[][]{{"hola","hola !"},{"sos independiente","mis pesos son propios ."}};for(String[] row:rows)out.put(new JSONObject().put("question",row[0]).put("answer",row[1]).put("origin","authored_project_examples"));return out;}
 static JSONArray data(Context c,String split)throws Exception{JSONArray own=defaultRows(split),users=new JSONArray(ModelDepot.prefs(c).getString("chatData","[]"));for(int i=0;i<users.length();i++){JSONObject row=users.getJSONObject(i);if(row.getString("split").equals(split))own.put(new JSONObject().put("question",row.getString("question")).put("answer",row.getString("answer")).put("origin","user"));}return own;}
 static String trainChat(Context c)throws Exception{String revision=ModelDepot.revision(c,"chat");BananaTransformer model=chat(c);JSONArray train=data(c,"train"),eval=data(c,"eval");Set<String> keys=new HashSet<>();for(int i=0;i<train.length();i++)keys.add(ChatLanguage.normalize(train.getJSONObject(i).getString("question")));for(int i=0;i<eval.length();i++)if(keys.contains(ChatLanguage.normalize(eval.getJSONObject(i).getString("question"))))throw new IllegalArgumentException("La misma pregunta aparece en entrenamiento y evaluación.");JavaChat.phase("Chat: calculando características del Transformer propio…");List<HeadTrainer.Token> a=tokens(model,train),b=tokens(model,eval),anchors=tokens(model,defaultRows("anchor"));float[][] old=HeadTrainer.copy(model.head),targets=HeadTrainer.distributions(anchors,model.head,model.headBias);double before=HeadTrainer.nll(b,model.head,model.headBias);JavaChat.phase("Chat: actualizando pesos de salida por gradiente…");HeadTrainer.chat(a,anchors,targets,model.head,model.headBias);double after=HeadTrainer.nll(b,model.head,model.headBias),drift=HeadTrainer.divergence(anchors,targets,model.head,model.headBias),delta=HeadTrainer.distance(old,model.head);boolean accepted=after<before-1e-5&&drift<=.003&&delta>0;JSONObject report=new JSONObject().put("kind","chat").put("method","SGD output projection, frozen Transformer body").put("before",before).put("after",after).put("anchorKL",drift).put("weightDeltaL2",delta).put("trainTokens",a.size()).put("evalTokens",b.size()).put("epochs",8).put("accepted",accepted).put("trainExamples",train.length()).put("evalExamples",eval.length()).put("metric","teacher_forced_token_NLL");ModelDepot.prefs(c).edit().putString("chatReport",report.toString()).commit();if(accepted){ByteArrayOutputStream bytes=new ByteArrayOutputStream();model.save(bytes);File file=ModelDepot.save(c,"chat",bytes.toByteArray());try(InputStream in=new FileInputStream(file)){BananaTransformer loaded=new BananaTransformer(in,c.getAssets().open("chat34/vocab.txt"),c.getAssets().open("chat34/tokenizer.json"));if(Math.abs(HeadTrainer.nll(b,loaded.head,loaded.headBias)-after)>1e-6)throw new IOException("El checkpoint no reproduce la evaluación.");}ModelDepot.publish(c,"chat",file,report,revision);}return (accepted?"Entrené y activé pesos nuevos de Banana Chat.":"Entrené un candidato de Chat; conservé los pesos activos porque no pasó el criterio.")+"\n"+report.toString(2)+"\nSólo se ajustó la proyección de salida. Menor pérdida sobre estas preguntas no garantiza mejor conversación general. Los ejemplos locales no son un benchmark externo.";}
 static float[] rgba(int color){return new float[]{((color>>>16)&255)/255f,((color>>>8)&255)/255f,(color&255)/255f,(color>>>24)/255f};}
 static String trainPixel(Context c)throws Exception{return trainPixel(c,false);}
 static String trainPixel(Context c,boolean deep)throws Exception{String revision=ModelDepot.revision(c,"pixel");PixelGenerator model=new PixelGenerator(ModelDepot.open(c,"pixel"));SceneDraft scene=MobileCore.scene(c);SceneDraft.Actor actor=scene==null?null:scene.get(scene.focused);Bitmap target;int type=0,color=0xfff8d061,acc=0,expression=0,view=0;String origin="own_authored_procedural_target";if(actor!=null&&!actor.reference.isEmpty()){type=PixelGenerator.type(actor.kind);if(type<0||type>8)throw new IllegalArgumentException("Entrenamiento disponible para los9 tipos del modelo principal.");color=Scene.bodyColor(actor.kind,actor.look);acc=NeuralSprites.accessory(actor.look);expression=Appearance.has(actor.look,"triste")?1:Appearance.has(actor.look,"sorprendido|sorprendida")?2:0;view=NeuralSprites.viewIndex(actor.view);if(view==2)view=1;if(view==3)view=2;target=BitmapFactoryCompat.decode(c,actor.reference);origin="user_imported_reference";}else try(InputStream in=c.getAssets().open("training/banana-own-target.png")){target=BitmapFactory.decodeStream(in);}if(target==null)throw new IOException("No pude abrir la referencia.");Bitmap scaled=Bitmap.createScaledBitmap(target,128,128,true);int[] pixels=new int[16384];scaled.getPixels(pixels,0,128,0,0,128,128);List<HeadTrainer.Pixel> train=new ArrayList<>(),eval=new ArrayList<>(),replay=new ArrayList<>();float[] condition=model.conditionFor(type,color,acc,expression,0);condition[23]=condition[24]=condition[25]=0;condition[23+view]=1;JavaChat.phase("Pixel: extrayendo características de muestras de la imagen…");for(int y=0;y<16;y++)for(int x=0;x<16;x++){if(Thread.currentThread().isInterrupted())throw new IOException("Entrenamiento cancelado.");int px=x*8+3,py=y*8+3;HeadTrainer.Pixel row=new HeadTrainer.Pixel(deep?model.coordinates(condition,px,py):model.features(model.coordinates(condition,px,py)),rgba(pixels[py*128+px]));if(((x+y)&1)==0)train.add(row);else eval.add(row);}float[] control=model.conditionFor(type==1?2:1,0xff629cdb,0,0,0);for(int y=0;y<8;y++)for(int x=0;x<8;x++){float[] features=model.features(model.coordinates(control,x*16+7,y*16+7)),z=HeadTrainer.logits(features,model.weights[3],model.biases[3]);for(int j=0;j<4;j++)z[j]=HeadTrainer.sigmoid(z[j]);replay.add(new HeadTrainer.Pixel(deep?model.coordinates(control,x*16+7,y*16+7):features,z));}float[][][] allOld=deep?DeepPixelTrainer.copy(model):null;float[][] old=HeadTrainer.copy(model.weights[3]);double before=deep?DeepPixelTrainer.loss(model,eval):HeadTrainer.mse(eval,model.weights[3],model.biases[3]);JavaChat.phase(deep?"Pixel: retropropagando por las cuatro capas…":"Pixel: actualizando pesos RGBA por gradiente…");if(deep)DeepPixelTrainer.train(model,train,replay);else HeadTrainer.pixel(train,replay,model.weights[3],model.biases[3]);double after=deep?DeepPixelTrainer.loss(model,eval):HeadTrainer.mse(eval,model.weights[3],model.biases[3]),drift=deep?DeepPixelTrainer.loss(model,replay):HeadTrainer.mse(replay,model.weights[3],model.biases[3]),delta=deep?DeepPixelTrainer.distance(model,allOld):HeadTrainer.distance(old,model.weights[3]);boolean accepted=after<before-1e-7&&drift<=.002&&delta>0;JSONObject report=new JSONObject().put("kind","pixel").put("method",deep?"SGD backpropagation all four character model layers":"SGD RGBA output layer, frozen neural features").put("trainedLayers",deep?4:1).put("before",before).put("after",after).put("anchorMSE",drift).put("weightDeltaL2",delta).put("trainSamples",train.size()).put("evalSamples",eval.size()).put("epochs",deep?2:12).put("accepted",accepted).put("origin",origin).put("type",type).put("color",color).put("accessory",acc).put("expression",expression).put("view",view).put("metric","alpha_weighted_RGBA_MSE_on_interleaved_pixels");ModelDepot.prefs(c).edit().putString("pixelReport",report.toString()).commit();if(accepted){ByteArrayOutputStream bytes=new ByteArrayOutputStream();model.save(bytes);File file=ModelDepot.save(c,"pixel",bytes.toByteArray());try(InputStream in=new FileInputStream(file)){PixelGenerator loaded=new PixelGenerator(in);if(Math.abs((deep?DeepPixelTrainer.loss(loaded,eval):HeadTrainer.mse(eval,loaded.weights[3],loaded.biases[3]))-after)>1e-7)throw new IOException("El checkpoint no reproduce la evaluación.");}JSONArray preview=new JSONArray();PixelGenerator bank;try(InputStream in=c.getAssets().open("training/pixel-bank-base.bin")){bank=new PixelGenerator(in);}for(int y=0;y<16;y++)for(int x=0;x<16;x++){float[] features=model.features(model.coordinates(condition,x*8+3,y*8+3)),a=HeadTrainer.logits(features,model.weights[3],model.biases[3]),b=HeadTrainer.logits(bank.features(bank.coordinates(condition,x*8+3,y*8+3)),bank.weights[3],bank.biases[3]);for(int j=0;j<4;j++)preview.put(a[j]-b[j]);}ModelDepot.publish(c,"pixel",file,report,revision,preview);}return (accepted?"Entrené y activé pesos nuevos de Banana Pixel.":"Entrené un candidato de Pixel; conservé los pesos activos porque no pasó el criterio.")+"\n"+report.toString(2)+(deep?"\nSe entrenaron las cuatro capas del modelo principal de personajes. Chat y las otras redes conservan sus capas. ":"\nSe ajustó la capa RGBA del modelo principal. ")+"La evaluación usa píxeles separados de la misma imagen: no prueba generalización a imágenes nuevas ni calidad perceptual universal. El resto de modelos de Pixel se conserva.";}
 static String summary(Context c,String kind)throws Exception{String raw=ModelDepot.prefs(c).getString(kind+"Report","");if(!raw.isEmpty())return raw;JSONObject baked=ModelDepot.report(c,kind);return baked==null?"sin candidato":baked.toString();}
 static BananaEngine.Result handle(Context c,String input)throws Exception{String q=ChatLanguage.normalize(input);if(q.equals("usa el modelo entrenado pixel")){if(!ModelDepot.active(c,"pixel"))return MobileCore.say(c,"Todavía no hay pesos entrenados de Pixel activos.","aprendizaje_local");SceneDraft before=MobileCore.scene(c);if(before==null||before.get(before.focused)==null)return MobileCore.say(c,"Elegí un personaje para usar la generación entrenada.","aprendizaje_local");SceneDraft next=before.copy();next.get(next.focused).reference="";BananaProject.edit(c,before,next);BananaEngine.Result result=MobileCore.say(c,"Retiré la referencia de este personaje para usar su generación neuronal. Conservé su identidad y las acciones.","escena");result.changed=true;return result;}Matcher sample=Pattern.compile("(?isu)^ejemplo chat (entrenamiento|evaluacion):\\s*("+JavaTextPlan.LIT+")\\s*=>\\s*("+JavaTextPlan.LIT+")\\s*$").matcher(input.trim());if(!q.matches("entrena chat|reentrena chat|entrena banana chat|entrena pixel|reentrena pixel|entrena banana pixel|estado entrenamiento neuronal|informe entrenamiento neuronal|deshace entrenamiento chat|deshace entrenamiento pixel")&&!sample.matches())return null;JavaChat.owner=Thread.currentThread();try{String text;if(sample.matches()){JSONArray data=new JSONArray(ModelDepot.prefs(c).getString("chatData","[]"));if(data.length()>=24)throw new IllegalArgumentException("Hasta24 ejemplos propios de Chat en esta fase.");String question=JavaTextPlan.decode(sample.group(2)),answer=JavaTextPlan.decode(sample.group(3));if(question.length()>160||answer.length()>160||question.trim().isEmpty()||answer.trim().isEmpty())throw new IllegalArgumentException("Pregunta y respuesta:1 a160 caracteres.");data.put(new JSONObject().put("question",question).put("answer",answer).put("split",sample.group(1).equalsIgnoreCase("entrenamiento")?"train":"eval").put("origin","user"));if(!ModelDepot.prefs(c).edit().putString("chatData",data.toString()).commit())throw new IOException("No pude guardar el ejemplo.");text="Guardé tu ejemplo con su origen y separación de entrenamiento/evaluación. Todavía no cambié los pesos.";}else if(q.startsWith("deshace"))text=ModelDepot.undo(c,q.endsWith("chat")?"chat":"pixel");else if(q.contains("estado")||q.contains("informe"))text="Entrenamiento neuronal real · Chat y Pixel\nChat: "+summary(c,"chat")+"\nPixel: "+summary(c,"pixel")+"\nChat puede ajustar su salida o reentrenar el Transformer completo si me pedís mejorarlo más a fondo. Pixel puede ajustar la salida o entrenar las cuatro capas del modelo principal de personajes si me pedís mejorarlo más a fondo. Podés pedirme que mejore los pesos de Chat, de Pixel o de ambos, que vuelva a los anteriores o que prepare la app con esos cambios. Pixel usa la referencia importada del personaje enfocado, o una referencia propia incluida si no hay una.";else text=q.endsWith("pixel")?trainPixel(c):trainChat(c);return MobileCore.say(c,text,"aprendizaje_local");}catch(Exception e){return MobileCore.say(c,"No completé un entrenamiento nuevo: "+AndroidRepair.summary(e),"aprendizaje_local");}finally{JavaChat.owner=null;JavaChat.progress="";}}
}
